/// Translate text using a cloud provider.
func translate(_ text: String, sourceIsChinese: Bool, provider: AIProvider, model: String) async throws -> String {
    let system = AITranslationPromptBuilder.instructions
    let user = AITranslationPromptBuilder.request(text: text, sourceIsChinese: sourceIsChinese)
    let result = try await chat(provider: provider, model: model, system: system, user: user, maxTokens: 2048)
    return result.trimmingCharacters(in: .whitespacesAndNewlines)
}

tool_input.new_string:
/// Translate text using a cloud provider.
///
/// Requests the shared one-field JSON envelope rather than a bare string:
/// anything the model writes around that field — a preface, an outline of
/// the passage, a translator's note — is then dropped by the parser instead
/// of being displayed, spoken, and saved to history as the translation.
func translate(_ text: String, sourceIsChinese: Bool, provider: AIProvider, model: String) async throws -> String {
    let system = AITranslationPromptBuilder.instructions
        + "\n\n"
        + AITranslationPromptBuilder.jsonOutputContract
    let user = AITranslationPromptBuilder.request(text: text, sourceIsChinese: sourceIsChinese)
    let raw = try await chat(
        provider: provider,
        model: model,
        system: system,
        user: user,
        jsonMode: true,
        maxTokens: AITranslationPromptBuilder.tokenBudget(forSourceLength: text.count)
    )
    return try AITranslationResponseParser.translation(from: raw)
}

