                        reading: "láilóng qùmài",
                        meaning: "the whole story, the ins and outs",
                        note: "A chengyu; sounds bookish in casual speech."
                    ),
                ]
            ),
            onSave: { _ in },
            isSaved: { _ in false }
        )
        .padding()
    }
}

